(54311, 'Psalms 145:5', 'Psalms', 145, 5, 'دوی به کوي ستا د جلال او شان او شوکت خبرې او زه به کومه غور ستا په عجیبه کارونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_5.mp3', '', 1761754199, 1761754199),
(54312, 'Psalms 145:6', 'Psalms', 145, 6, 'خلک به خبرې کوي ستا د قوي او هیبتناکه کارو په هکله او بیانوم به زه لویي د ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_6.mp3', '', 1761754199, 1761754199),
(54313, 'Psalms 145:7', 'Psalms', 145, 7, 'بیانوي به هغوی زیاتې نېکۍ ستا او وایي سندرې به په خوشحالۍ سره ستا د عدالت په هکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_7.mp3', '', 1761754199, 1761754199),
(54314, 'Psalms 145:8', 'Psalms', 145, 8, 'څښتن رحیم او مهربانه دی زر نه په قهریږي او مینه یې ډېره او تلپاتې ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_8.mp3', '', 1761754199, 1761754199),
(54315, 'Psalms 145:9', 'Psalms', 145, 9, 'مهربانه په هرچا دی هغه او رحم کوي په خپلو ټولو مخلوقاتو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_9.mp3', '', 1761754199, 1761754199),
(54316, 'Psalms 145:10', 'Psalms', 145, 10, 'ټول مخلوقات به ستا ای څښتنه وکړي شکر ستا او ستا وفادار خلک به ووایي ثنا د ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_10.mp3', '', 1761754199, 1761754199),
(54317, 'Psalms 145:11', 'Psalms', 145, 11, 'هغوی به خبرې وکړي ستا د پاچاهۍ د جلال په هکله او بیانوي به ستا قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_11.mp3', '', 1761754199, 1761754199),
(54318, 'Psalms 145:12', 'Psalms', 145, 12, 'ترڅو خبر شي ټول خلک ستا له زورورو کارو او ستا د شاهۍ له شان شوکته څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_12.mp3', '', 1761754199, 1761754199),
(54319, 'Psalms 145:13', 'Psalms', 145, 13, 'ابدي ده پاچاهي ستا او تل ترتله به پاچا یې ته خپلو وعدو ته وفادار دی څښتن او ټولو کارونو کې رحیم دی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_13.mp3', '', 1761754199, 1761754199),
(54320, 'Psalms 145:14', 'Psalms', 145, 14, 'کوي مرسته د هغو خلکو سره چې په تکلیف کې وي لاس ورکوي کړوپ شویو خلکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_14.mp3', '', 1761754199, 1761754199),
(54321, 'Psalms 145:15', 'Psalms', 145, 15, 'ټولو ژوندیو موجوداتو د امید سترګې نیولې تاته چې په خپل وخت ورته خواړه ورکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_15.mp3', '', 1761754199, 1761754199),
(54322, 'Psalms 145:16', 'Psalms', 145, 16, 'ته یې پرېمانه ورکوې هغوی ته او پوره کوې غوښتنې د ټول ژوندي مخلوق', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_16.mp3', '', 1761754199, 1761754199),
(54323, 'Psalms 145:17', 'Psalms', 145, 17, 'ټولو کارونو کې عادل دی څښتن او ټولو کارونو کې رحیم دی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_17.mp3', '', 1761754199, 1761754199),
(54324, 'Psalms 145:18', 'Psalms', 145, 18, 'څښتن نژدې دی هغه چاته چې ورته کړي فریاد هغه چاته چې په اخلاص ورته فریاد کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_18.mp3', '', 1761754199, 1761754199),
(54325, 'Psalms 145:19', 'Psalms', 145, 19, 'پوره کوي غوښتنې د هغو چې وېره کړي له هغه هغه یې اوري فریادونه او خلاصون ورکوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_19.mp3', '', 1761754199, 1761754199),
(54326, 'Psalms 145:20', 'Psalms', 145, 20, 'څوک چې کوي ورسره مینه نو ساتي یې هغه خو بدکاران به ټول تباه کړي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_20.mp3', '', 1761754199, 1761754199),
(54327, 'Psalms 145:21', 'Psalms', 145, 21, 'ثنا او صفت به زه د څښتن کومه ټول مخلوقات دې تل صفت کړي د هغه د پاک نوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms145_verse_21.mp3', '', 1761754199, 1761754199),
(54328, 'Numbers 26:1', 'Numbers', 26, 1, 'له وبا څخه وروسته څښتن موسی او د هارون کاهن زوی العازار ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_1.mp3', '', 1761754199, 1761754199),
(54329, 'Numbers 26:2', 'Numbers', 26, 2, '«د اسراییلو د ټول قوم سرشمېرنه د کورنیو له مخې وکړئ، یعنې د هغو ټولو خلکو چې عمر یې شل کاله یا زیات وي او جنګ کولای شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_2.mp3', '', 1761754199, 1761754199),
(54330, 'Numbers 26:3', 'Numbers', 26, 3, 'په هغه وخت کې د اسراییلو ټول قوم د موآب په ډاګونو کې اریحا ته مخامخ د اردن د سیند په غاړه خېمې ودرولې وې. نو موسی او العازار کاهن د اسراییلو مشرانو ته د دې سرشمېرنې په اړه داسې لارښوونه وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_3.mp3', '', 1761754199, 1761754199),
(54331, 'Numbers 26:4', 'Numbers', 26, 4, '«لکه څنګه چې څښتن موسی ته حکم کړی دی هغه ټول اسراییلیان چې عمر یې شل کاله یا زیات وي وشمارئ.» دا هغه اسراییلیان دي چې د مصر څخه راوتلي وو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_4.mp3', '', 1761754199, 1761754199),
(54332, 'Numbers 26:5', 'Numbers', 26, 5, 'د روبین د قبیلې څخه (روبین د یعقوب مشر زوی ؤ): د حنوک، فلو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_5.mp3', '', 1761754199, 1761754199),
(54333, 'Numbers 26:6', 'Numbers', 26, 6, 'حصرون او کرمي طایفې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_6.mp3', '', 1761754199, 1761754199),
(54334, 'Numbers 26:7', 'Numbers', 26, 7, 'د دې طایفو شمېر ۴۳۷۳۰ تنه نارینه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_7.mp3', '', 1761754199, 1761754199),
(54335, 'Numbers 26:8', 'Numbers', 26, 8, 'د فلو اولاده: الیاب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_8.mp3', '', 1761754199, 1761754199),
(54336, 'Numbers 26:9', 'Numbers', 26, 9, 'او د هغه زامن نموییل، داتان او ابیرام. (دا هماغه داتان او ابیرام دي چې د قوم له خوا غوره شوي وو، خو هغوی د موسی او هارون سره مخالفت وکړ او د قورح د پیروانو سره یوځای شول او د څښتن په وړاندې یې سرکښي وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_9.mp3', '', 1761754199, 1761754199),
(54337, 'Numbers 26:10', 'Numbers', 26, 10, 'نو ځمکه پرانیستل شوه او هغوی یې د قورح سره ژوندي تېر کړل. په هماغه وخت کې اور ۲۵۰ تنه له منځه یووړل. دا هغو نورو اسراییلیانو ته د خبرداري په توګه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_10.mp3', '', 1761754199, 1761754199),
(54338, 'Numbers 26:11', 'Numbers', 26, 11, 'خو د قورح زامن ونه وژل شول.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_11.mp3', '', 1761754199, 1761754199),
(54339, 'Numbers 26:28', 'Numbers', 26, 28, 'د یوسف قبیلې چې هغه د دوو زامنو یعنې منسي او افرایم پلار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_28.mp3', '', 1761754199, 1761754199),
(54340, 'Numbers 26:51', 'Numbers', 26, 51, 'په لست کې د اسراییلو د ټولو کسانو شمېر ۶۰۱۷۳۰ تنه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_51.mp3', '', 1761754199, 1761754199),
(54341, 'Numbers 26:52', 'Numbers', 26, 52, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_52.mp3', '', 1761754199, 1761754199),
(54342, 'Numbers 26:53', 'Numbers', 26, 53, '«د کنعان ځمکه په دغو قبیلو باندې د هغو کسانو د شمېر له مخې چې په هرې قبیلې کې دي ووېشه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_53.mp3', '', 1761754199, 1761754199),
(54343, 'Numbers 26:57', 'Numbers', 26, 57, 'د لاوي په قبیلې کې دا طایفې شاملې وې: جرشون، قهات، مراري،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_57.mp3', '', 1761754199, 1761754199),
(54344, 'Numbers 26:58', 'Numbers', 26, 58, 'او همدارنګه د لبني، حبرون، محلي، موشي او قورح طایفې. قهات د عمرام نیکه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_58.mp3', '', 1761754199, 1761754199),
(54345, 'Numbers 26:59', 'Numbers', 26, 59, 'د عمرام د ښځې نوم یوکابد ؤ چې د لاوي د اولادې څخه وه او په مصر کې زېږېدلې وه. د عمرام او یوکابد درې اولادونه وو، یعنې هارون، موسی او مریم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_59.mp3', '', 1761754199, 1761754199),
(54346, 'Numbers 26:60', 'Numbers', 26, 60, 'هارون د ناداب، ابیهو، العازار او ایتامار پلار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_60.mp3', '', 1761754199, 1761754199),
(54347, 'Numbers 26:61', 'Numbers', 26, 61, 'خو ناداب او ابیهو په هغه وخت کې مړه شول کله چې هغوی څښتن ته ناپاکه اور وړاندې کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_61.mp3', '', 1761754199, 1761754199),
(54348, 'Numbers 26:62', 'Numbers', 26, 62, 'د لاوي په قبیله کې ۲۳۰۰۰ تنه نارینه وو او په هغو کې داسې هلکان هم وو چې عمرونه یې لږ تر لږه یوه میاشت وو. د نورو قبیلو سره د هغوی نومونه په لست کې نه وو، ځکه چې هغوی ته په کنعان کې ځمکه نه ورکول کېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_62.mp3', '', 1761754199, 1761754199),
(54349, 'Numbers 26:63', 'Numbers', 26, 63, 'په هغه وخت کې چې اسراییلیانو د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ خېمې ودرولې وې، موسی او العازار هغوی وشمېرل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_63.mp3', '', 1761754199, 1761754199),
(54350, 'Numbers 26:64', 'Numbers', 26, 64, 'د هغو خلکو څخه چې موسی او هارون د سینا په دښته کې شمېرلي وو، یو هم ژوندی پاتې نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_64.mp3', '', 1761754199, 1761754199),
(54351, 'Numbers 26:65', 'Numbers', 26, 65, 'څښتن ویلي وو چې پرته د یفنه د زوی کالیب او د نون زوی یوشع څخه نور ټول به په دښته کې مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers26_verse_65.mp3', '', 1761754199, 1761754199),
(54352, 'Leviticus 12:1', 'Leviticus', 12, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_1.mp3', '', 1761754199, 1761754199),
(54353, 'Leviticus 12:2', 'Leviticus', 12, 2, '«اسراییلیانو ته ووایه چې کله یوه ښځه امیدواره شي او زوی وزېږوي، هغه به اووه ورځې د خپلې میاشتینۍ ناروغۍ په شان ناپاکه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_2.mp3', '', 1761754199, 1761754199),
(54354, 'Leviticus 12:3', 'Leviticus', 12, 3, 'په اتمه ورځ دې هلک سنت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_3.mp3', '', 1761754199, 1761754199),
(54355, 'Leviticus 12:4', 'Leviticus', 12, 4, 'بیا باید هغه ښځه د وینې د بهېدلو څخه د پاکېدلو دپاره دري دېرش ورځې صبر وکړي. هغه باید هېڅ یو پاک شي ته لاس ورنه وړي او نه دې د پاکېدلو د ورځو د پوره کېدلو پورې سپېڅلې خېمې ته ورننوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_4.mp3', '', 1761754199, 1761754199),
(54356, 'Leviticus 12:5', 'Leviticus', 12, 5, 'که چېرې هغه لور وزېږوي، دا ښځه به څوارلس ورځې ناپاکه وي، لکه څنګه چې د میاشتینۍ ناروغۍ په دوران کې ناپاکه کیږي. بیا باید هغه ښځه د وینې د بهېدلو څخه د پاکېدلو دپاره شپږشپېته ورځې صبر وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_5.mp3', '', 1761754199, 1761754199),
(54357, 'Leviticus 12:6', 'Leviticus', 12, 6, 'کله چې د یو زوی یا د یوې لور د زېږولو دپاره د پاکېدلو ورځې خلاصې شي، هغه دې د سپېڅلې خېمې د دروازې په خوله کې کاهن ته ورشي. هغه دې یو وری چې یو کلن وي د سوځېدونکې نذرانې دپاره او یوه قمري یا یوه کوتره د ګناه د نذرانې دپاره راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_6.mp3', '', 1761754199, 1761754199),
(54358, 'Leviticus 12:7', 'Leviticus', 12, 7, 'کاهن به د هغې دپاره د کفارې د ادا کولو په خاطر هغه د څښتن په حضور کې وړاندې کړي او هغه ښځه به د وینې د بهېدلو څخه پاکه شي. دا اصول د هغې ښځې دپاره دي چې یو هلک یا یوه انجلۍ وزېږوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_7.mp3', '', 1761754199, 1761754199),
(54359, 'Leviticus 12:8', 'Leviticus', 12, 8, 'که چېرې دا ښځه یو وری نه شي اخیستلی، نو دوه کوترې یا دوه قمري ګانې دې راوړي، یوه د سوځېدونکې نذرانې دپاره او بله د ګناه د نذرانې دپاره او کاهن به د هغې د ناپاکۍ د لېرې کولو دپاره کفاره ادا کړي او هغه به پاکه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus12_verse_8.mp3', '', 1761754199, 1761754199),
(54360, 'Hosea 2:1', 'Hosea', 2, 1, 'نو خپل اسراییلي ورونه عمي یعنې «زما قوم» او خپلې خویندې روحامه یعنې «چې په چا باندې رحم شوی وي» وبولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_1.mp3', '', 1761754199, 1761754199),
(54361, 'Hosea 2:2', 'Hosea', 2, 2, 'څښتن داسې وایي: «ای زما اولادونو، خپله مور یعنې اسراییل ورټئ، ځکه چې هغه نوره زما ښځه نه ده او زه د هغې مېړه نه یم. هغې ته ووایئ چې زناکاري او بدلمني پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_2.mp3', '', 1761754199, 1761754199),
(54362, 'Hosea 2:3', 'Hosea', 2, 3, 'که نه، نو زه به هغه داسې لوڅه لغړه کړم، لکه څنکه چې د پیدا کېدلو په ورځ لوڅه لغړه وه. زه به هغه د وچې او شاړې ځمکې په شان کړم او هغه به د تندې له لاسه مړه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_3.mp3', '', 1761754199, 1761754199),
(54363, 'Hosea 2:6', 'Hosea', 2, 6, 'نو زه به د هغې لاره د اغزیو په بوټو باندې بنده کړم او یو دېوال به جوړ کړم چې هغه ونه شي کولای خپله لاره پیدا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_6.mp3', '', 1761754199, 1761754199),
(54364, 'Hosea 2:7', 'Hosea', 2, 7, 'هغه به خپلو عاشقانو پسې منډې وهي، خو هغوی ته به وررسېدلی نه شي. هغه به خپلو عاشقانو پسې ګرځي، خو هغوی به نه شي پیدا کولای. نو بیا به وایي: ‹زه بېرته خپل لومړني مېړه ته ځم، ځکه چې زما دپاره د اوس نه هغه وخت ډېر ښه ؤ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_7.mp3', '', 1761754199, 1761754199),
(54365, 'Hosea 2:8', 'Hosea', 2, 8, 'هغه په دې نه پوهېدله چې زه هغه ذات یم چې هغې ته مې غلې دانې، شراب، د زیتونو تېل او ډېر سپین او سره زر ورکول، خو هغې ورڅخه د بعل بت ته د عبادت کولو دپاره کار اخیسته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_8.mp3', '', 1761754199, 1761754199),
(54366, 'Hosea 2:9', 'Hosea', 2, 9, 'نو زه به د حاصلاتو د راټولو په وخت کې د هغې نه د غلو دانو او شرابو نعمتونه بېرته واخلم او ما چې د کالیو دپاره ورته کومې وړۍ او کتان ورکړی ؤ، ترڅو هغه لوڅه پاتې نه شي، هغه به هم ورڅخه بېرته واخلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_9.mp3', '', 1761754199, 1761754199),
(54367, 'Hosea 2:10', 'Hosea', 2, 10, 'نو زه به هغه د خپلو عاشقانو په مخکې لوڅه کړم او هېڅوک به یې زما څخه خلاصولی نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_10.mp3', '', 1761754199, 1761754199),
(54368, 'Hosea 2:11', 'Hosea', 2, 11, 'زه به د هغې ټولې خوشحالۍ، د هغې کلني او میاشتیني اخترونه او د هغې د سبت د ورځې جشنونه یعنې د هغې ټولو اخترونو ته د پای ټکی کېږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_11.mp3', '', 1761754199, 1761754199),
(54369, 'Hosea 2:12', 'Hosea', 2, 12, 'زه به د هغې د انګورو تاکونه او د انځرو ونې چې هغې به ویل چې عاشقانو به یې ورته د خدمتونو په بدل کې ورکول، له منځه یوسم. زه به د هغې د انګورو تاکونه او د مېوو باغونه په ځنګل باندې بدل کړم او ځنګلي ځناور به د هغه مېوه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_12.mp3', '', 1761754199, 1761754199),
(54370, 'Hosea 2:13', 'Hosea', 2, 13, 'زه به هغې ته د هغو اخترونو په خاطر چې زه یې په کې هېر کړی وم او د بعل بتانو ته به یې خوشبویۍ سوځولې او خپلو عاشقانو ته د ورتګ په وخت کې به یې ګاڼې اچولې، سزا ورکړم.» څښتن داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_13.mp3', '', 1761754199, 1761754199),
(54371, 'Hosea 2:14', 'Hosea', 2, 14, 'نو زه څښتن به هغه یوځل بیا په مینه راګېره کړم او دښتې ته به یې بوځم او په خوږو خبرو سره به د هغې زړه بېرته لاسته راوړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_14.mp3', '', 1761754199, 1761754199),
(54372, 'Hosea 2:15', 'Hosea', 2, 15, 'هغې چې د انګورو کوم تاکونه لرل، هغه به ورته بېرته ورکړم او د هغې دپاره به د عخور دره یعنې «د مصیبت دره» د هیلې په دروازې باندې بدله کړم. هغه به زما خبره هماغه شان مني، لکه څنګه چې یې د ځوانۍ په وخت کې کله چې د مصر څخه راوتله، زما خبره منله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_15.mp3', '', 1761754199, 1761754199),
(54373, 'Hosea 2:16', 'Hosea', 2, 16, 'څښتن وایي چې په هغه وخت کې به بیا ماته خپل مېړه ووایي او نور به ماته خپل بعل یعنې بادار نه وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_16.mp3', '', 1761754199, 1761754199),
(54374, 'Hosea 2:17', 'Hosea', 2, 17, 'زه به هېڅکله هغه پرېنږدم چې په خپله خوله باندې د بعل د بتانو نوم واخلي او هغه به نور په یاد نه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_17.mp3', '', 1761754199, 1761754199),
(54375, 'Hosea 2:18', 'Hosea', 2, 18, 'په هغه وخت کې به زه د ټولو ځنګلي حیواناتو او د هوا د مرغانو او خزندو سره یو لوظ وکړم، ترڅو هغوی زما قوم ته زیان ونه رسوي. زه به د هغه وطن نه تورې او لیندې ورکې کړم او خپل قوم به پرېږدم چې په ارامۍ او امن سره خپل ژوند وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_18.mp3', '', 1761754199, 1761754199),
(54376, 'Hosea 2:19', 'Hosea', 2, 19, 'څښتن وایي: ای اسراییله، تا نه به جوړه کړمه خپله ښځه او زه به دې خپله کړمه تل دپاره زه به رښتینی او عادل اوسم زه به کوم درسره تلپاتې مینه او رحم به کړم درسره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_19.mp3', '', 1761754199, 1761754199),
(54377, 'Hosea 2:20', 'Hosea', 2, 20, 'زه به تاته وفادار یمه او تا به کړم زه خپله ښځه او ما به وپېژنې ته د څښتن په توګه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_20.mp3', '', 1761754199, 1761754199),
(54378, 'Hosea 2:23', 'Hosea', 2, 23, 'هغه وطن کې به مېشت کړمه خپل قوم او کړم به نېکمرغه هغوی مینه به وکړم هغو خلکو سره چې یادېدل به په دې نوم «چې رحم نه وي شوی چا باندې» او هغو خلکو ته چې یادېدل به «زما قوم نه دی» ورته به وایمه زه چې «زما قوم یئ تاسو» او هغوی به راکړي ځواب چې «ته یې خدای زمونږه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea2_verse_23.mp3', '', 1761754199, 1761754199),
(54379, 'Ezekiel 34:1', 'Ezekiel', 34, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_1.mp3', '', 1761754199, 1761754199),
(54380, 'Ezekiel 34:2', 'Ezekiel', 34, 2, '«ای فاني انسانه، د اسراییلو د واکمنانو په ضد نبوت وکړه. هغوی ته ووایه چې زه څښتن تعالی هغوی ته داسې وایم: ‹ای د اسراییلو شپنو، افسوس ستاسو په حال! تاسو په خپلو ځانونو باندې پام کوئ، ایا خپلو پسونو ته باید پاملرنه ونه کړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_2.mp3', '', 1761754199, 1761754199),
(54381, 'Ezekiel 34:3', 'Ezekiel', 34, 3, 'تاسو د هغوی وازګه خورئ، د هغو د وړیو نه جوړ شوي کالي اغوندئ، چاغ پسونه حلالوئ او هغه خورئ، خو هېڅکله په خپلو رمو باندې پام نه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_3.mp3', '', 1761754199, 1761754199),
(54382, 'Ezekiel 34:4', 'Ezekiel', 34, 4, 'تاسو د کمزورو پسونو ساتنه نه ده کړې، د ناروغو پسونو علاج مو نه دی کړی، د مات شویو هډوکو رغونه مو نه ده کړې، هغو چې خپله لاره ورکه کړې ده، هغه مو بېرته نه دي راوستي او ورک شوي مو نه دي لټولي. د دې په ځای په هغو باندې مو په زور‌زیاتي حکومت کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_4.mp3', '', 1761754199, 1761754199),
(54383, 'Ezekiel 34:5', 'Ezekiel', 34, 5, 'په دې خاطر چې هغو پسونو شپون نه درلود، نو هرې خواته خواره واره شول او د وحشي حیواناتو د خوراک شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_5.mp3', '', 1761754199, 1761754199),
(54384, 'Ezekiel 34:6', 'Ezekiel', 34, 6, 'نو زما پسونه په غرونو او لوړو غونډیو باندې سرګردانه ګرځېدل. هغوی د ځمکې په مخ خواره واره شول او هېچا نه لټول او نه یې کوښښ کاوه چې هغه راپیدا کړي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_6.mp3', '', 1761754199, 1761754199),
(54385, 'Ezekiel 34:7', 'Ezekiel', 34, 7, 'نو ای شپنو، زما کلام ته غوږ ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_7.mp3', '', 1761754199, 1761754199),
(54386, 'Ezekiel 34:8', 'Ezekiel', 34, 8, 'زه څښتن تعالی تاسو ته داسې وایم، څرنګه چې زما پسونو شپون نه درلود، نو وحشي حیواناتو ورباندې حمله وکړه، هغوی یې ووژل او ویې خوړل. زما شپنو د پسونو د لټولو کوښښ ونه کړ. هغوی په خپلو ځانونو باندې پام کاوه او په پسونو باندې یې پام نه کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_8.mp3', '', 1761754199, 1761754199),
(54387, 'Ezekiel 34:9', 'Ezekiel', 34, 9, 'نو ای شپنو، زما کلام ته غوږ ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_9.mp3', '', 1761754199, 1761754199),
(54388, 'Ezekiel 34:10', 'Ezekiel', 34, 10, 'زه څښتن تعالی داسې وایم چې زه ستاسو په ضد یم. زه به تاسو سره حساب وکړم او بیا به هېڅکله تاسو پرېنږدم چې د هغوی شپانه اوسئ. بیا به هېڅکله تاسو پرېنږدم چې یوازې په خپلو ځانونو باندې پام وکړئ. زه به خپل پسونه ستاسو د خولې نه خلاص کړم او تاسو به پرېنږدم چې هغوی وخورئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_10.mp3', '', 1761754199, 1761754199),
(54389, 'Ezekiel 34:11', 'Ezekiel', 34, 11, '«زه څښتن تعالی تاسو ته داسې وایم چې زه به په خپله خپل پسونه ولټوم او په هغو باندې به پام وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_11.mp3', '', 1761754199, 1761754199),
(54390, 'Ezekiel 34:12', 'Ezekiel', 34, 12, 'لکه څنګه چې شپانه خپل ورک شوي پسونه لټوي او هغه بېرته راټولوي، زه به هم خپل پسونه چې په هغې تیاره او بدبخته ورځ خواره واره شوي وو، ولټوم او د ټولو ځایونو نه به یې بېرته راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_12.mp3', '', 1761754199, 1761754199),
(54391, 'Ezekiel 34:13', 'Ezekiel', 34, 13, 'زه به هغوی د پردیو وطنونو نه راوباسم، هغوی به سره راټول کړم او بېرته به یې خپل وطن ته راولم. زه به هغوی د اسراییلو په غرونو، تنګیو او د وطن په ټولو مېشته شوي ځایونو کې ماړه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_13.mp3', '', 1761754199, 1761754199),
(54392, 'Ezekiel 34:14', 'Ezekiel', 34, 14, 'زه به هغوی په ښو واښو باندې ماړه کړم او د هغوی څړځایونه به د اسراییلو په لوړو غرونو باندې وي. هغوی به په ښو څړځایونو کې ارام ومومي او د اسراییلو په غرونو کې به پرېمانه واښه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_14.mp3', '', 1761754199, 1761754199),
(54393, 'Ezekiel 34:15', 'Ezekiel', 34, 15, 'زه به خپله د خپلو پسونو شپون اوسم او د هغوی دپاره به د ارام کولو ځای پیدا کړم. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_15.mp3', '', 1761754199, 1761754199),
(54394, 'Ezekiel 34:16', 'Ezekiel', 34, 16, 'زه به ورک شوي پسونه ولټوم، بې‌لارې شوي به بېرته راولم، د مات شویو هډوکو رغونه به وکړم او کوم چې ناروغه شوي دي د هغو علاج به وکړم، خو چاغ او قوي پسونه به له منځه یوسم، ځکه زه به د هغوی دپاره باانصافه شپون اوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_16.mp3', '', 1761754199, 1761754199),
(54395, 'Ezekiel 34:17', 'Ezekiel', 34, 17, 'نو ای زما رمې، زه څښتن تعالی تاسو ته داسې وایم چې زه به ستاسو هر یو په هکله قضاوت وکړم او ښه حیوان به د بد حیوان نه او پسونه د سېرلیو نه بېل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_17.mp3', '', 1761754199, 1761754199),
(54396, 'Ezekiel 34:18', 'Ezekiel', 34, 18, 'ایا دا ستاسو دپاره بس نه ؤ چې په خپله ښه واښه خورئ، خو کوم واښه چې تاسو نه پاتې کیږي، هغه تر‌پښو لاندې کوئ؟ ایا دا ستاسو دپاره بس نه ؤ چې صافې اوبه څښئ، خو پاتې اوبه چټلوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_18.mp3', '', 1761754199, 1761754199),
(54397, 'Ezekiel 34:19', 'Ezekiel', 34, 19, 'ولې زما نور پسونه هغه واښه خوري چې تاسو تر‌پښو لاندې کړي دي او هغه اوبه څښي چې تاسو چټلې کړې دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_19.mp3', '', 1761754199, 1761754199),
(54398, 'Ezekiel 34:20', 'Ezekiel', 34, 20, 'نو اوس زه څښتن تعالی تاسو ته داسې وایم: ‹ګورئ، زه به په خپله ستاسو د چاغو او ډنګرو پسونو ترمنځ قضاوت وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_20.mp3', '', 1761754199, 1761754199),
(54399, 'Ezekiel 34:21', 'Ezekiel', 34, 21, 'تاسو کمزوري پسونه په خپلو اوږو، ورنونو او ښکرونو باندې یوې خواته ټېله کړي دي او د رمې نه مو هغوی خواره واره کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_21.mp3', '', 1761754199, 1761754199),
(54400, 'Ezekiel 34:22', 'Ezekiel', 34, 22, 'په دې خاطر به زه خپله رمه وژغورم او نور به یې پرېنږدم چې ظلم ورسره وشي. زه به د خپل هر یو حیوان په هکله قضاوت وکړم او ښه به د بد نه بېل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_22.mp3', '', 1761754199, 1761754199),
(54401, 'Ezekiel 34:23', 'Ezekiel', 34, 23, 'زه به هغوی ته د خپل خدمتګار داود په شان بل پاچا ورکړم چې د هغوی یوازینی شپون شي او په هغوی باندې به پام وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_23.mp3', '', 1761754199, 1761754199),
(54402, 'Ezekiel 34:24', 'Ezekiel', 34, 24, 'زه به د هغوی څښتن خدای یم او زما د خدمتګار داود په شان یو پاچا به د هغوی واکمن وي. ما څښتن داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_24.mp3', '', 1761754199, 1761754199),
(54403, 'Ezekiel 34:25', 'Ezekiel', 34, 25, '«زه به د هغوی سره د سولې او امن لوظ وکړم. د هغوی وطن به د خطرناکو حیواناتو نه خلاص کړم، ترڅو زما پسونه وکولای شي په امن سره په صحرا کې واوسیږي او په ځنګلونو کې ویده شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_25.mp3', '', 1761754199, 1761754199),
(54404, 'Ezekiel 34:26', 'Ezekiel', 34, 26, 'زه به نوموړې سیمې او په اورشلیم کې زما د غونډۍ شاوخوا حاصلخېزه کړم. زه به په سم موسم کې باران ووروم او دا به د برکت سبب وګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_26.mp3', '', 1761754199, 1761754199),
(54405, 'Ezekiel 34:27', 'Ezekiel', 34, 27, 'ونې به مېوې ونیسي، ځمکې به حاصلات ورکړي او هر یو به په خپل وطن کې په امن سره ژوند تېر کړي. کله چې زه د خپلو خلکو جغونه مات او هغوی د غلامۍ نه خلاص کړم، بیا به هغوی پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_27.mp3', '', 1761754199, 1761754199),
(54406, 'Ezekiel 34:28', 'Ezekiel', 34, 28, 'پردي قومونه به هغوی لوټ نه کړي او وحشي حیوانات به هغوی ونه وژني او نه به یې وخوري. هغوی به په امن کې واوسیږي او هېڅوک به هغوی ونه وېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_28.mp3', '', 1761754199, 1761754199),
(54407, 'Ezekiel 34:29', 'Ezekiel', 34, 29, 'زه به هغوی ته داسې ځمکه ورکړم چې په حاصل ورکولو کې مشهوره وي. نور به هغوی له قحطۍ او لوږې ونه مري او پردي قومونه به نور هغوی ته سپکاوی ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_29.mp3', '', 1761754199, 1761754199),
(54408, 'Ezekiel 34:30', 'Ezekiel', 34, 30, 'نو بیا به هغوی په دې پوه شي چې زه د اسراییلو څښتن خدای د هغوی سره یم او هغوی یعنې د اسراییلو قوم، زما خلک دي. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_30.mp3', '', 1761754199, 1761754199),
(54409, 'Ezekiel 34:31', 'Ezekiel', 34, 31, 'ای زما پسونو، تاسو زما د څړځایونو پسونه یئ، تاسو زما قوم یئ او زه ستاسو خدای یم. څښتن تعالی داسې وایي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel34_verse_31.mp3', '', 1761754199, 1761754199),
(54410, 'Deuteronomy 3:1', 'Deuteronomy', 3, 1, 'بیا مونږ شمال ته د باشان په لور روان شولو او عوج پاچا د خپل ټول لښکر سره راووت چې د ادرعي ښار ته نژدې زمونږ سره وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_1.mp3', '', 1761754199, 1761754199);